# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">METEOROLOJİK GÖZLEMLER, TAHMİN VE GÜNLÜK HAYATA ETKİLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">METEOROLOJİK VERİ VE ERKEN UYARI</text>\n  <text x="42" y="95" font-size="11" fill="#1e3a8a">• Yer İstasyonları, Radarlar ve Uydular (MGM)</text>\n  <text x="42" y="120" font-size="11" fill="#1e3a8a">• Yeşil Kod: Normal hava durumu, tehlike yok</text>\n  <text x="42" y="145" font-size="11" font-weight="bold" fill="#ca8a04">• Sarı Kod: Potansiyel tehlike, dikkatli olunmalı</text>\n  <text x="42" y="170" font-size="11" font-weight="bold" fill="#ea580c">• Turuncu Kod: Tehlikeli hava, hasar riski, tedbir</text>\n  <text x="42" y="195" font-size="11" font-weight="bold" fill="#dc2626">• Kırmızı Kod: Çok tehlikeli/ekstrem hava olayı</text>\n  <text x="182" y="224" text-anchor="middle" font-size="10.5" fill="#1d4ed8">MeteoUyarı sistemi can ve mal kaybını önler.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SEKTÖRLERE VE YAŞAMA ETKİSİ</text>\n  <text x="377" y="95" font-size="11" fill="#14532d">• Tarım: Zirai don, dolu, kuraklık; ekim-hasat</text>\n  <text x="377" y="120" font-size="11" fill="#14532d">• Ulaşım: Sis, buzlanma, fırtına (kara-hava-deniz)</text>\n  <text x="377" y="145" font-size="11" fill="#14532d">• Enerji: Rüzgâr (RES), Güneş (GES) ve HES üretimi</text>\n  <text x="377" y="170" font-size="11" fill="#14532d">• Günlük Yaşam: Giyim, sağlık, açık hava planları</text>\n  <text x="377" y="195" font-size="11" fill="#14532d">• Afet Yönetimi: Sel, taşkın, çığ ve fırtına önlemleri</text>\n  <text x="517" y="224" text-anchor="middle" font-size="10.5" fill="#15803d">Gözleme dayalı tahmin sürdürülebilir yaşamı destekler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İKLİM SİSTEMİNİN 5 TEMEL BİLEŞENİ (KÜRESEL ETKİLEŞİM)</text>\n  <circle cx="350" cy="145" r="46" fill="#fef08a" stroke="#ca8a04" stroke-width="2.5"/>\n  <text x="350" y="141" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">İKLİM</text>\n  <text x="350" y="157" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">SİSTEMİ</text>\n  <rect x="30" y="50" width="175" height="65" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="117" y="73" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. ATMOSFER (Hava Küre)</text>\n  <text x="117" y="92" text-anchor="middle" font-size="10" fill="#1e3a8a">En hareketli ve hızlı değişen</text>\n  <text x="117" y="106" text-anchor="middle" font-size="10" fill="#1e3a8a">bileşen; enerji ve nem taşır.</text>\n  <rect x="495" y="50" width="175" height="65" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="582" y="73" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0369a1">2. HİDROSFER (Su Küre)</text>\n  <text x="582" y="92" text-anchor="middle" font-size="10" fill="#0c4a6e">Okyanuslar, denizler, göller;</text>\n  <text x="582" y="106" text-anchor="middle" font-size="10" fill="#0c4a6e">ısıyı depolar ve akıntılarla dağıtır.</text>\n  <rect x="30" y="165" width="175" height="65" rx="8" fill="#f1f5f9" stroke="#64748b" stroke-width="2"/>\n  <text x="117" y="188" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#334155">3. KRİYOSFER (Buz Küre)</text>\n  <text x="117" y="207" text-anchor="middle" font-size="10" fill="#475569">Buzullar, kar örtüsü; yüksek</text>\n  <text x="117" y="221" text-anchor="middle" font-size="10" fill="#475569">albedo ile güneş ışığını yansıtır.</text>\n  <rect x="495" y="165" width="175" height="65" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="582" y="188" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">4. LİTOSFER (Taş Küre)</text>\n  <text x="582" y="207" text-anchor="middle" font-size="10" fill="#78350f">Kıtalar, dağlar, yükselti, bakı;</text>\n  <text x="582" y="221" text-anchor="middle" font-size="10" fill="#78350f">hava kütlelerini ve yağışı yönlendirir.</text>\n  <rect x="262" y="205" width="176" height="45" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">5. BİYOSFER (Canlı Küre)</text>\n  <text x="350" y="240" text-anchor="middle" font-size="10" fill="#14532d">Bitkiler ve canlılar; karbon/su döngüsü</text>\n  <line x1="205" y1="95" x2="308" y2="128" stroke="#64748b" stroke-width="2"/>\n  <line x1="495" y1="95" x2="392" y2="128" stroke="#64748b" stroke-width="2"/>\n  <line x1="205" y1="185" x2="308" y2="162" stroke="#64748b" stroke-width="2"/>\n  <line x1="495" y1="185" x2="392" y2="162" stroke="#64748b" stroke-width="2"/>\n  <line x1="350" y1="191" x2="350" y2="205" stroke="#64748b" stroke-width="2"/>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İKLİM SİSTEMİNİN DEĞİŞKENLERİ (ELEMANLARI)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">TEMEL İKLİM DEĞİŞKENLERİ</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#7c2d12">1. Hava Sıcaklığı (°C — Termometre):</text>\n  <text x="52" y="112" font-size="10.5" fill="#431407">Güneş radyasyonu ile oluşur; en temel değişkendir.</text>\n  <text x="42" y="136" font-size="11.5" font-weight="bold" fill="#7c2d12">2. Hava Basıncı (hPa / mb — Barometre):</text>\n  <text x="52" y="152" font-size="10.5" fill="#431407">Sıcaklık, yükselti, yer çekimi ve Dünya\'nın hareketi.</text>\n  <text x="42" y="176" font-size="11.5" font-weight="bold" fill="#7c2d12">3. Rüzgâr (m/s, km/sa — Anemometre):</text>\n  <text x="52" y="192" font-size="10.5" fill="#431407">Yüksek basınçtan (YB) alçak basınca (AB) hava akımı.</text>\n  <text x="42" y="216" font-size="11.5" font-weight="bold" fill="#7c2d12">4. Nem ve Yağış (Higrometre / Plüvyometre)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">DEĞİŞKENLER ARASI NEDENSEL İLİŞKİ</text>\n  <rect x="380" y="84" width="275" height="32" rx="6" fill="#f3e8ff"/>\n  <text x="517" y="104" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Güneş Enerjisi → Sıcaklık Farkı Oluşturur</text>\n  <rect x="380" y="126" width="275" height="32" rx="6" fill="#f3e8ff"/>\n  <text x="517" y="146" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Sıcaklık Farkı → Basınç Farkı ve Rüzgâr Doğurur</text>\n  <rect x="380" y="168" width="275" height="32" rx="6" fill="#f3e8ff"/>\n  <text x="517" y="188" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Sıcaklık Artışı → Buharlaşma ve Mutlak Nemi Artırır</text>\n  <text x="517" y="222" text-anchor="middle" font-size="10.5" fill="#6b21a8">Yükselen nemli hava soğur → Yoğuşma ve Yağış</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
